/* Toolbox Learn 2.4.5: offline-first topic library, OIC practice, review and mock exams. */
(()=>{'use strict';const root=document.getElementById('view');if(!root)return;
const files={study:'maritime-study.json',cbt:'toolbox-cbt.json',speak:'articulation-presence.json',oic:'oic-practice.json',gmdss:'gmdss-review.json',olpindex:'olp-topic-index.json'};const data={};const STORE='toolbox-learn-v245';let state={screen:'home',track:'deck',topic:'all',query:'',mode:'study',index:0,answers:{},order:[],selected:null};let saved={bookmarks:[],attempts:[],completed:{}};try{saved={...saved,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(saved))}catch{}};const active=()=>!!document.querySelector('nav [data-tab="learn"].active');
const questions=()=>{let a=state.screen==='gmdss'?(data.gmdss?.questions||[]):state.screen==='cbt'?(data.cbt?.questions||[]):(data.oic?.questions||[]).filter(x=>x.track===state.track);return a.filter(x=>(state.topic==='all'||(x.topic||x.topicId)===state.topic)&&(!state.query||[x.question,x.topic,x.topicId,...(x.options||[])].join(' ').toLowerCase().includes(state.query.toLowerCase())))};
const qtopic=x=>x.topic||data.cbt?.topics?.find(t=>t.id===x.topicId)?.title||x.topicId||'General';const opts=x=>x.options||[];const correct=x=>typeof x.answer==='number'?x.answer:Array.isArray(x.answers)&&x.answers.length===1?x.answers[0]:typeof x.correctIndex==='number'?x.correctIndex:typeof x.correct==='number'?x.correct:typeof x.answerIndex==='number'?x.answerIndex:null;
function header(label,title,subtitle){return `<div class="tl-head"><span class="tl-eyebrow">${esc(label)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>`}function back(to='home'){return `<button class="tl-back" data-go="${to}">← Back</button>`}
const tlSceneArt={"bridge":"data:image/svg+xml;base64,","engine":"data:image/svg+xml;base64,","psc":"data:image/svg+xml;base64,","business":"data:image/svg+xml;base64,","finance":"data:image/svg+xml;base64,"};
let tlMissionFilter='all';
const tlMissionGroup=id=>['business','finance'].includes(id)?(id==='business'?'business':'finance'):'maritime';
function tlMissionTiles(){return Object.entries(missions).filter(([id])=>tlMissionFilter==='all'||tlMissionGroup(id)===tlMissionFilter).map(([id,m])=>`<button data-mission="${id}" class="tl-mission tl-mission-${id}" style="--tl-order:${Object.keys(missions).indexOf(id)}"><span class="tl-mission-art"><img loading="lazy" src="${tlSceneArt[id]}" alt="${esc(m.title)} mission illustration"></span><span class="tl-mission-content"><b>${esc(m.role)}</b><strong>${esc(m.title)}</strong><small>${esc(m.intro)}</small><em>OPEN CASE FILE <span aria-hidden="true">↗</span></em></span></button>`).join('')}
function tlMissionFilters(){return `<div class="tl-missionfilters" role="group" aria-label="Filter missions">${[['all','All missions'],['maritime','At sea'],['business','Business'],['finance','Finance']].map(([id,title])=>`<button data-mfilter="${id}" class="${tlMissionFilter===id?'selected':''}">${title}</button>`).join('')}</div>`}
function home(){const attempts=Array.isArray(saved.attempts)?saved.attempts:[];const lessonsDone=Object.keys(saved.completed||{}).length;const bookmarked=Array.isArray(saved.bookmarks)?saved.bookmarks.length:0;return `<div class="tl-local-progress" aria-label="Learning activity saved on this device"><strong>Your learning activity</strong><div class="tl-local-progress-stats"><span><b>${attempts.length}</b> review sessions</span><span><b>${lessonsDone}</b> lessons marked complete</span><span><b>${bookmarked}</b> bookmarks</span></div><small>Saved on this device · Not an official qualification</small></div><div class="tl-hero"><span class="tl-hero-kicker">TOOLBOX · OFFLINE LEARNING</span><h1>What do you need today?</h1><p>Find your reviewer in seconds, or step into a story where your choices matter.</p></div><div class="tl-shortcuts"><button class="tl-shortcut tl-shortcut-deck" data-open="deck"><span class="tl-shortcut-symbol">◈</span><span><b>OIC REVIEWER</b><strong>Deck</strong><small>Navigation & watchkeeping</small></span><i>↗</i></button><button class="tl-shortcut tl-shortcut-engine" data-open="engine"><span class="tl-shortcut-symbol">⚙</span><span><b>OIC REVIEWER</b><strong>Engine</strong><small>Machinery & engineering</small></span><i>↗</i></button><button class="tl-shortcut tl-shortcut-olp" data-open="olpindex"><span class="tl-shortcut-symbol">▤</span><span><b>QUICK FIND</b><strong>OLP / CBT</strong><small>Numbered topic index</small></span><i>↗</i></button><button class="tl-shortcut tl-shortcut-gmdss" data-open="gmdss"><span class="tl-shortcut-symbol">◉</span><span><b>RADIO REVIEW</b><strong>GMDSS</strong><small>Historical practice bank</small></span><i>↗</i></button></div><div class="tl-sectiontitle tl-missions-heading"><div><span class="tl-eyebrow">THE INTERACTIVE EXPERIENCE</span><h2>Maritime Missions</h2><small>Open a case. Take command. Live with your decisions.</small></div><span class="tl-mission-count">5 CASE FILES</span></div><button class="tl-mission-hero" data-mission="bridge"><img src="${tlSceneArt.bridge}" alt="Bridge emergency scene"><span class="tl-hero-overlay"><b>FEATURED MISSION · DECK</b><strong>Bridge Emergency</strong><small>Reduced visibility. Closing traffic. You're the officer on watch.</small><em>OPEN THE CASE FILE <span>↗</span></em></span></button>${tlMissionFilters()}<div class="tl-missions">${tlMissionTiles()}</div><details class="tl-more"><summary>More study & interactive systems <span>⌄</span></summary><div class="tl-grid">${[['cbt','CBT Practice Questions','Existing question library'],['study','Maritime Study','Interactive learning material'],['speak','Communication Practice','Professional communication']].map(([id,t,d])=>`<button class="tl-course" data-open="${id}"><strong>${t}</strong><small>${d}</small></button>`).join('')}</div></details><p class="tl-notice">For independent learning only. Verify historical keys and follow approved onboard procedures.</p>`}

const missions={
business:{role:'Life · Startup Founder',title:'Build Your Shore Business',art:'CEO / 04',intro:'You are a seafarer starting a small shore-side business. Manage cash, customers and risk.',steps:[['You have ₱120,000 saved. A business opportunity needs capital. What comes first?',[['Validate demand with a low-cost pilot before committing',2,'Pilot validation protects cash and tests real demand.'],['Spend everything on equipment immediately',0,'Fixed costs arrived before proof of customers.'],['Borrow more without a cash forecast',0,'Debt increases risk before revenue is established.']]],['Your first customers request a discount. What do you do?',[['Calculate costs and contribution margin before pricing',2,'You protect margin while understanding customer needs.'],['Agree to any price to grow',0,'Revenue without margin may destroy cash.'],['Ignore customer feedback',0,'You miss an opportunity to improve the offer.']]],['Occupancy or sales are lower than expected. Your next move?',[['Review cash runway, interview prospects and test improvements',2,'A measured response preserves options.'],['Double advertising spend without measurement',0,'Unmeasured spending shortens runway.'],['Hide the issue from partners',0,'Poor transparency undermines trust.']]],['Your business partner wants to use company funds personally. What do you do?',[['Set written separation of personal and business money',2,'Controls and clear records protect the business.'],['Allow it without documentation',0,'Untracked withdrawals create conflict.'],['Stop all bookkeeping',0,'Without records decisions become guesswork.']]],['Demand rises sharply. What is the smart expansion?',[['Check unit economics and capacity, then scale in stages',2,'Growth must remain operationally and financially sustainable.'],['Sign a long lease immediately',0,'Large commitments increase downside.'],['Ignore quality to maximize sales',0,'Service failures can damage retention.']]],['A profitable month ends. What do you prioritize?',[['Set aside taxes, reserves and planned reinvestment',2,'Profit is not the same as free cash.'],['Spend all revenue as personal income',0,'Revenue includes costs and obligations.'],['Assume next month will be identical',0,'Forecasts need scenarios and buffers.']]]]},
finance:{role:'Life · Financial Captain',title:'The Road to Financial Freedom',art:'MONEY / 05',intro:'Balance family support, emergency savings, investing and life after sailing.',steps:[['You receive your first salary after a long contract. What is your first move?',[['List obligations, build a budget and protect an emergency reserve',2,'A plan gives every peso a job.'],['Invest the entire salary in one asset',0,'Concentration and lack of liquidity increase risk.'],['Spend now and budget later',0,'Unplanned spending makes goals harder.']]],['Your family asks for support above your budget. What do you do?',[['Set a sustainable amount and explain your limits',2,'Sustainable support protects both your family and future.'],['Promise more than you earn',0,'Unsustainable commitments create future pressure.'],['Take high-interest debt to cover it',0,'Borrowing for recurring costs can compound the problem.']]],['A friend promises guaranteed high returns. Your response?',[['Verify regulation, risks, fees and whether returns are plausible',2,'Guaranteed high returns are a warning sign.'],['Transfer money immediately',0,'Urgency and promises are red flags.'],['Borrow money to double the investment',0,'Leverage magnifies losses.']]],['Your ship contract ends and income pauses. What matters most?',[['Use the shore-leave budget and preserve emergency cash',2,'Irregular income requires planned liquidity.'],['Assume a new contract starts tomorrow',0,'Timing is uncertain.'],['Use credit for all expenses',0,'Debt may grow before the next salary.']]],['You want income from investments. What is a prudent approach?',[['Diversify and evaluate cash flow, risk, liquidity and time horizon',2,'Income is not guaranteed and risk must be managed.'],['Assume every asset pays monthly',0,'Many investments pay nothing or fluctuate.'],['Ignore taxes and fees',0,'Net returns matter.']]],['Your financial plan is working. What is the next step?',[['Review goals, rebalance and maintain reserves',2,'Financial freedom is built through repeated decisions.'],['Quit immediately without checking runway',0,'A plan needs sustainable numbers.'],['Increase lifestyle costs to match every raise',0,'Lifestyle inflation can erase progress.']]]]},

bridge:{role:'Deck · Officer of the Watch',title:'Traffic in Reduced Visibility',art:'BRIDGE / 01',intro:'A contact closes as visibility falls.',steps:[['Visibility drops and radar shows a contact approaching. What is your first priority?',[['Assess risk using all available means and notify the Master as required',2,'Good situational awareness and escalation.'],['Assume the other vessel will keep clear',-2,'Assumptions can conceal developing collision risk.'],['Continue unchanged without additional monitoring',-2,'Failure to reassess increases risk.']]],['The contact bearing changes little and range decreases. What now?',[['Treat as possible collision risk and use systematic assessment',2,'Correct: bearing and range trends demand attention.'],['Wait for visual confirmation before assessing',-2,'Restricted visibility requires appropriate use of available means.'],['Make an arbitrary alteration without assessment',-1,'Unplanned maneuvers may create additional risk.']]],['The lookout reports an uncertain sound signal. What do you do?',[['Confirm information, maintain lookout, and follow applicable restricted-visibility requirements',2,'Integrating lookout and radar is sound bridge practice.'],['Ignore the report because radar is working',-2,'One sensor should not replace a proper lookout.'],['Order the lookout to stop reporting',-2,'This weakens bridge resource management.']]],['The Master arrives. What briefing is most useful?',[['Concise position, traffic, risk assessment, actions and uncertainties',2,'A structured briefing supports shared situational awareness.'],['Only say everything is under control',-1,'Vague briefings hide important uncertainties.'],['Hand over without describing the traffic',-2,'Incomplete handover increases risk.']]],['A junior officer challenges your assessment. How do you respond?',[['Invite evidence, verify together, and adjust if needed',2,'Constructive challenge improves bridge teamwork.'],['Dismiss the concern because of rank',-2,'Authority gradient can suppress safety-critical information.'],['Stop monitoring while debating',-2,'Situational awareness must be maintained.']]],['The situation stabilizes. What completes the learning cycle?',[['Record relevant events and debrief the bridge team',2,'Documentation and debrief reinforce lessons.'],['Forget the incident because no collision occurred',-1,'Near misses can reveal important weaknesses.'],['Declare the simulator score proof of real-world competence',-2,'Training games do not certify competence.']]]]},
engine:{role:'Engine · Chief Engineer',title:'Unexpected Machinery Alarm',art:'ENGINE / 02',intro:'A propulsion-related alarm appears during maneuvering.',steps:[['An abnormal machinery alarm sounds during maneuvering. First response?',[['Verify indications, communicate promptly, and follow vessel procedures',2,'Verify the condition and coordinate with the bridge.'],['Silence the alarm and ignore the reading',-2,'Acknowledging an alarm is not resolving its cause.'],['Change several controls without diagnosis',-2,'Uncoordinated actions may compound the fault.']]],['Two instruments disagree. What is the best approach?',[['Cross-check independent indications and assess reliability',2,'Corroboration reduces single-instrument error.'],['Trust whichever reading looks normal',-2,'Convenience is not evidence.'],['Disconnect both instruments',-2,'This can remove useful protection.']]],['The bridge asks whether propulsion is available. You are uncertain.',[['State confirmed facts, uncertainty, and immediate next update',2,'Accurate, timely communication supports safe decisions.'],['Promise full availability without evidence',-2,'False certainty creates operational risk.'],['Ignore the bridge until the issue disappears',-2,'Delayed communication limits coordination.']]],['An engineer proposes bypassing a protective interlock.',[['Reject unauthorized bypass and follow approved procedures',2,'Safety barriers must not be casually defeated.'],['Approve it to save time',-2,'Bypassing safeguards can escalate damage.'],['Ask them to conceal the bypass',-2,'Concealment is incompatible with safe operation.']]],['The alarm clears unexpectedly. What next?',[['Investigate cause and verify stable operation under approved procedures',2,'A cleared alarm is not proof of a corrected fault.'],['Assume the system repaired itself',-1,'Intermittent faults still require attention.'],['Delete the alarm record',-2,'Records help diagnose recurrence.']]],['The watch ends. What do you hand over?',[['Findings, limitations, actions, logs and pending follow-up',2,'Complete handover protects continuity.'],['Only say it is fine now',-1,'Missing context weakens the next watch.'],['Leave without telling the next watch',-2,'Unreported issues may recur.']]]]},
psc:{role:'Shared · Master / Chief Officer',title:'Port State Control Visit',art:'PSC / 03',intro:'An inspector requests records and a safety demonstration.',steps:[['An inspector boards and requests safety documents. What do you do?',[['Verify credentials, cooperate, and provide accurate current records',2,'Professional, transparent cooperation is appropriate.'],['Delay indefinitely without explanation',-2,'Obstruction undermines trust.'],['Provide altered records',-2,'Falsifying records is unacceptable.']]],['A maintenance record contains a discrepancy.',[['Disclose the discrepancy and explain documented corrective action',2,'Transparency and traceable correction matter.'],['Rewrite history to conceal it',-2,'Fabricated records create serious compliance concerns.'],['Blame a junior crew member without checking',-1,'Accountability requires facts.']]],['The inspector asks for an emergency equipment demonstration.',[['Coordinate a safe demonstration with competent crew and approved procedures',2,'Safe, prepared demonstrations are essential.'],['Improvise an unsafe test to impress the inspector',-2,'Safety must take precedence.'],['Claim a test occurred when it did not',-2,'False claims undermine compliance.']]],['A crew member is unsure about their assigned duty.',[['Clarify duties, address the training gap, and report honestly',2,'Identifying and correcting gaps is constructive.'],['Coach the crew member to guess confidently',-2,'Guessing conceals a readiness issue.'],['Punish the crew member for speaking up',-2,'Fear discourages reporting.']]],['A deficiency is raised. What should the team do?',[['Understand the finding, document it, and agree corrective action',2,'A clear corrective-action process supports resolution.'],['Argue without reviewing evidence',-1,'Evidence-based discussion is more productive.'],['Hide related documents',-2,'Concealment increases risk.']]],['The inspection concludes. What is the best follow-up?',[['Review findings, assign owners, verify corrections and brief the crew',2,'Follow-through turns inspection findings into improvement.'],['Discard the report',-2,'Findings require tracking.'],['Assume the game result determines actual PSC outcome',-2,'Real inspection outcomes are determined by authorities.']]]]}
};
let missionState={id:null,step:0,score:0,log:[]};
function missionPage(){let m=missions[missionState.id];if(!m)return home();let i=missionState.step;if(i>=m.steps.length){let result=missionState.score>=9?'Strong judgment':missionState.score>=4?'Developing judgment':'Review recommended';return back()+header('MISSION DEBRIEF',m.title,result)+`<div class="tl-lesson"><h2>${missionState.score} / ${m.steps.length*2} points</h2><p>Training score only; not a certification or regulatory assessment.</p>${missionState.log.map((x,j)=>`<p><b>Chapter ${j+1}</b> · ${esc(x)}</p>`).join('')}<button class="tl-primary" data-mission="${missionState.id}">Replay mission</button></div>`}let s=m.steps[i];return back()+header(`${m.art} · CHAPTER ${i+1} / ${m.steps.length}`,m.title,`Role: ${m.role}`)+`<div class="tl-lesson tl-game tl-case-open"><div class="tl-case-file" aria-hidden="true"><span>CASE FILE</span><span>CONFIDENTIAL · TRAINING</span></div><img class="tl-scene" src="${tlSceneArt[missionState.id]}" alt="${esc(m.title)} illustrated mission scene"><div class="tl-gameprogress"><span style="width:${i/m.steps.length*100}%"></span></div><p class="tl-gamequestion">${esc(s[0])}</p>${s[1].map((o,j)=>`<button class="tl-gamechoice" data-mchoice="${j}">${esc(o[0])}</button>`).join('')}<p class="tl-notice">Choose the safest response based on the information provided. Actual operations require approved procedures.</p></div>`}

function bank(){let a=questions();let base=state.screen==='gmdss'?data.gmdss?.questions||[]:state.screen==='cbt'?data.cbt?.questions||[]:(data.oic?.questions||[]).filter(x=>x.track===state.track);let topics=[...new Set(base.map(qtopic))];let title=state.screen==='gmdss'?'GMDSS GOC · Historical 2012 Review':state.screen==='cbt'?'Toolbox CBT':state.track==='deck'?'OIC Navigational Watch':'OIC Engineering Watch';return back()+header('SEARCHABLE QUESTION LIBRARY',title,`${a.length} matching questions · offline-ready practice`)+`<div class="tl-tools"><input class="tl-search" id="tl-search" type="search" placeholder="Search question or keyword" value="${esc(state.query)}" aria-label="Search questions"><select id="tl-topic" aria-label="Filter topic"><option value="all">All topics</option>${topics.map(t=>`<option value="${esc(t)}" ${state.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="tl-mode"><button data-mode="study" class="${state.mode==='study'?'selected':''}">Study</button><button data-mode="practice" class="${state.mode==='practice'?'selected':''}">Practice</button><button data-mode="exam" class="${state.mode==='exam'?'selected':''}">Mock exam</button></div><div class="tl-actions"><button data-start="1" class="tl-primary">${state.mode==='exam'?'Start mock exam':state.mode==='practice'?'Practice filtered questions':'Study filtered questions'}</button><button data-bookmarks="1">Bookmarks (${saved.bookmarks.length})</button></div><div class="tl-list">${a.slice(0,100).map((q,i)=>`<button class="tl-item" data-question="${i}"><span><strong>${esc(q.question)}</strong><small>${esc(qtopic(q))} · ${saved.bookmarks.includes(q.id)?'Saved bookmark':'Review question'}</small></span><span>›</span></button>`).join('')||'<p>No matching questions. Try another keyword or topic.</p>'}</div><p class="tl-notice">Source: ${state.screen==='gmdss'?'GMDSS GOC EL7 (2012), source answer key. Historical material; current regulatory validity not confirmed.':state.screen==='cbt'?'Original Toolbox CBT bank; not official OLP answers.':'Toolbox original practice; not official MARINA question text.'} Always verify against current authoritative references.</p>`}
function session(){let id=state.order[state.index],q=(state.sessionQuestions||[]).find(x=>x.id===id);if(!q)return back(state.screen==='cbt'?'cbt':'bank')+'<p>No questions available.</p>';let ans=state.answers[id];let reveal=state.mode==='study'||state.revealed?.[id];let right=correct(q);return back('bank')+header(state.mode==='exam'?'MOCK EXAM':state.mode==='practice'?'PRACTICE':'STUDY',`Question ${state.index+1} of ${state.order.length}`,qtopic(q))+`<div class="tl-question"><div class="tl-qmeta"><span>${esc(qtopic(q))}</span><button data-bookmark="${esc(q.id)}">${saved.bookmarks.includes(q.id)?'★ Bookmarked':'☆ Bookmark'}</button></div><h2>${esc(q.question)}</h2>${opts(q).map((o,i)=>`<button class="tl-option ${ans===i?'chosen':''} ${reveal&&right===i?'right':''}" data-answer="${i}" ${reveal&&state.mode!=='study'?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(typeof o==='string'?o:o.label||o.text||'')}</button>`).join('')}${reveal?`<p class="tl-feedback">${right===null?'Answer key not available in source.':`Reference answer: ${String.fromCharCode(65+right)}. ${esc(q.explanation||'No explanation provided in the source.')}`}</p>`:state.mode==='practice'?'<button data-reveal="1">Check answer</button>':''}<div class="tl-actions"><button data-prev="1" ${state.index===0?'disabled':''}>Previous</button><button class="tl-primary" data-next="1">${state.index===state.order.length-1?'Finish & save':'Next question'}</button></div></div>`}
function summary(){let a=state.sessionQuestions||[],answered=state.order.filter(id=>state.answers[id]!==undefined),keyed=answered.filter(id=>correct(a.find(x=>x.id===id))!==null),good=keyed.filter(id=>state.answers[id]===correct(a.find(x=>x.id===id)));return back('bank')+header('SESSION COMPLETE','Review your progress',`${answered.length} answered · ${good.length}/${keyed.length} correct on keyed questions`)+`<div class="tl-actions"><button class="tl-primary" data-go="bank">Return to question library</button></div><p class="tl-notice">Results are stored locally on this device. This is not an official certification assessment.</p>`}
function lessons(){let rows=state.screen==='study'?data.study?.lessons||[]:data.speak?.days||[];return back()+header('OFFLINE LESSONS',state.screen==='study'?'Maritime Study':'Communication Practice','Choose a lesson to review.')+`<div class="tl-list">${rows.map((x,i)=>`<button class="tl-item" data-lesson="${i}"><span><strong>${esc(x.title||x.goal||'Day '+(x.day||i+1))}</strong><small>${saved.completed[state.screen+':'+i]?'Completed':'Open lesson'}</small></span>›</button>`).join('')}</div>`}
function lesson(){let rows=state.lessonParent==='study'?data.study?.lessons||[]:data.speak?.days||[];let x=rows[state.selected];if(!x)return lessons();return back(state.screen)+header('LEARNING MATERIAL',x.title||x.goal||'Day '+(x.day||state.selected+1),x.area||'')+`<div class="tl-question"><p>${esc(x.summary||x.description||x.content||x.goal||'See source learning materials for full lesson.')}</p>${(x.keyPoints||x.steps||[]).map(s=>`<p>${esc(typeof s==='string'?s:JSON.stringify(s))}</p>`).join('')}<button class="tl-primary" data-complete="1">${saved.completed[(state.lessonParent||state.screen)+':'+state.selected]?'Completed ✓':'Mark complete'}</button></div>`}
function olpIndex(){let a=(data.olpindex?.topics||[]).filter(x=>!state.query||[x.code,x.title].join(' ').toLowerCase().includes(state.query.toLowerCase()));return back()+header('OLP / CBT TOPIC FINDER','Find a module by number','2018 source index · reference only, not verified answers')+`<input class="tl-search" id="tl-search" type="search" placeholder="Search 0058, COLREG, pump..." value="${esc(state.query)}"><div class="tl-list">${a.map(x=>`<div class="tl-item"><span><strong>${esc(x.code)} · ${esc(x.title)}</strong><small>Original PDF page reference: ${esc(x.page)} · 2018 compilation</small></span></div>`).join('')}</div><p class="tl-notice">This is a topic finder, not an endorsed answer bank. Refer to your licensed source and current ship procedures.</p>`}
function paint(){if(!active())return;root.innerHTML=`<section class="tl-root tl-245">${state.screen==='home'?home():state.screen==='mission'?missionPage():['bank','cbt','gmdss'].includes(state.screen)?bank():state.screen==='olpindex'?olpIndex():state.screen==='session'?session():state.screen==='summary'?summary():state.screen==='lesson'?lesson():lessons()}</section>`}
function begin(single=null,bookmarkOnly=false){let a=questions();if(bookmarkOnly)a=a.filter(x=>saved.bookmarks.includes(x.id));if(single!==null)a=a.slice(single,single+1);if(state.mode==='exam'&&single===null){a=a.slice().sort(()=>Math.random()-.5).slice(0,Math.min(20,a.length))}state.sessionQuestions=a;state.order=a.map(x=>x.id);state.index=0;state.answers={};state.revealed={};state.screen='session';paint()}
root.addEventListener('input',e=>{if(!active()||e.target.id!=='tl-search')return;state.query=e.target.value;let pos=e.target.selectionStart;paint();let el=root.querySelector('#tl-search');el?.focus();el?.setSelectionRange(pos,pos)},true);
root.addEventListener('change',e=>{if(e.target.id==='tl-topic'){state.topic=e.target.value;paint()}},true);
root.addEventListener('click',e=>{if(!active())return;let b=e.target.closest('button[data-open],button[data-go],button[data-mode],button[data-start],button[data-question],button[data-answer],button[data-reveal],button[data-next],button[data-prev],button[data-bookmark],button[data-bookmarks],button[data-lesson],button[data-complete],button[data-mission],button[data-mchoice],button[data-mfilter]');if(!b)return;e.stopImmediatePropagation();if(b.dataset.mfilter){tlMissionFilter=b.dataset.mfilter;paint();return}else if(b.dataset.mission){missionState={id:b.dataset.mission,step:0,score:0,log:[]};state.screen='mission'}else if(b.dataset.mchoice!==undefined){let choice=missions[missionState.id].steps[missionState.step][1][Number(b.dataset.mchoice)];if(choice){missionState.score+=choice[1];missionState.log.push(choice[2]);missionState.step++;try{localStorage.setItem('toolbox-missions-last',JSON.stringify({id:missionState.id,score:missionState.score,completed:missionState.step>=missions[missionState.id].steps.length,date:new Date().toISOString()}))}catch{}}}else if(b.dataset.open){let v=b.dataset.open;state.screen=v==='deck'||v==='engine'?'bank':v;state.track=v==='engine'?'engine':'deck';state.topic='all';state.query='';state.mode='study'}else if(b.dataset.go){state.screen=b.dataset.go==='bank'?'bank':b.dataset.go;state.selected=null}else if(b.dataset.mode){state.mode=b.dataset.mode}else if(b.dataset.start){begin();return}else if(b.dataset.question!==undefined){begin(Number(b.dataset.question));return}else if(b.dataset.answer!==undefined){let id=state.order[state.index];state.answers[id]=Number(b.dataset.answer)}else if(b.dataset.reveal){state.revealed[state.order[state.index]]=true}else if(b.dataset.next){if(state.index<state.order.length-1)state.index++;else{let a=state.sessionQuestions||[];let keyed=a.filter(x=>correct(x)!==null);let good=keyed.filter(x=>state.answers[x.id]===correct(x)).length;saved.attempts.unshift({date:new Date().toISOString(),mode:state.mode,track:state.track,score:good,total:keyed.length});saved.attempts=saved.attempts.slice(0,100);persist();state.screen='summary'}}else if(b.dataset.prev){state.index=Math.max(0,state.index-1)}else if(b.dataset.bookmark){let id=b.dataset.bookmark;saved.bookmarks=saved.bookmarks.includes(id)?saved.bookmarks.filter(x=>x!==id):[...saved.bookmarks,id];persist()}else if(b.dataset.bookmarks){begin(null,true);return}else if(b.dataset.lesson!==undefined){state.selected=Number(b.dataset.lesson);state.lessonParent=state.screen;state.screen='lesson'}else if(b.dataset.complete){saved.completed[(state.lessonParent||state.screen)+':'+state.selected]=Date.now();persist();state.screen=state.lessonParent||'study'}paint()},true);
const observer=new MutationObserver(()=>{if(active()&&!root.querySelector('.tl-root'))paint()});observer.observe(root,{childList:true});document.querySelectorAll('nav [data-tab="learn"]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(paint)));
Promise.all(Object.entries(files).map(async([id,file])=>{try{let r=await fetch('assets/learning/'+file);if(!r.ok)throw Error('missing');data[id]=await r.json()}catch{data[id]={questions:[],lessons:[],days:[]}}})).then(paint);
})();
